 @PostMapping("/api/v1/orders") ResponseEntity<?> submit(HttpServletRequest r)throws IOException{
  AuthController.noQuery(r);var body=AuthRequests.object(r,Set.of("reviewId"));UUID review=ContactRequests.id(body.path("reviewId").isString()?body.path("reviewId").asString():null,"BODY","/reviewId"),rawKey=StockRequests.key(r);var selected=policy.select(r);String csrf=selected.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(r):null;
  var admission=tx.execute(status->sessions.replayAdmissionBuyer(selected.secret(),selected.transport()));throttle.admitApi(admission.actor(),true);byte[] identity=digest("key",rawKey),payload=digest("payload",review);
  Orders.Outcome outcome=retry(template->template.execute(status->{
   orders.lockReplay(admission.actor(),admission.buyer(),identity);
   UUID vendor=orders.replayVendor(admission.actor(),admission.buyer(),identity)
       .or(()->reviews.vendor(admission.buyer(),review))
       .orElseThrow(()->new OrderFailure(OrderFailure.Reason.NOT_FOUND));
   var principal=sessions.authenticateForWorkspace(selected.secret(),selected.transport(),admission.buyer(),Set.of(vendor));
   if(selected.transport()==SessionTransport.BROWSER){sessions.requireCsrf(selected.secret(),csrf);}
   var scope=authorization.require(principal.accountId(),admission.buyer(),member(principal.accountId()).country(),BusinessCapability.SUBMIT_OR_CANCEL_BUYER_ORDER);
   Instant at=clock.instant().truncatedTo(ChronoUnit.MILLIS);
   var replay=orders.replay(scope.accountId(),scope.organizationId(),review,identity,payload,at);
   var result=replay.isPresent()?new Orders.Outcome(replay.get(),null,List.of())
       :orders.submit(scope.accountId(),sessions.currentDisplayName(scope.accountId()),scope.organizationId(),scope.country(),review,identity,payload,at);
   sessions.recordSuccessfulActivity(selected.secret(),selected.transport());
   return result;
  }));
  return outcome(outcome,admission.buyer(),201);
 }
